import { test, expect } from '@playwright/test';

test.describe('Form Validation Error Messages', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form'); // Replace with the actual form URL
  });

  test('should display validation error for empty name field', async ({ page }) => {
    await page.getByLabel('Name').fill('');
    await page.getByRole('button', { name: 'Submit' }).click();
    const errorMessage = await page.getByText('Name is required');
    await expect(errorMessage).toBeVisible();
  });

  test('should display validation error for invalid email format', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email');
    await page.getByRole('button', { name: 'Submit' }).click();
    const errorMessage = await page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();
  });
});
